// Measured resource use: resources.data.js, generated by bench/export_resources.py from bench/published/resources_*.jsonl.
const RES = (typeof window !== "undefined" && window.RIDX_RESOURCES) || null;


const FORMAT = [
  ["Header · magic RIDX, v5", "416 B, section offsets"], ["String pool", "names, paths, signatures"],
  ["Files", "16 B / entry, content hash"], ["Definitions", "40 B / entry"],
  ["Definitions hash index", "FNV-1a, by path"], ["Owner index · deref table", "members, receiver chains"],
  ["References, sorted by span", "48 B / entry"], ["References target hash index", "find references"],
  ["Types · type arena", "28 B / entry, structural"], ["Impls · fields · generics · where", "16–32 B / entry"],
  ["Uses · macros · cfgs · lang items · notes", "8–28 B / entry"],
];
const TONES = ["#f74c00", "#ff9900", "#ffb347", "#00d2ff", "#38bdf8", "#7dd3fc", "#bae6fd", "#c4b5fd", "#a78bfa", "#8b5cf6", "#7c3aed"];

const LSP = [
  ["Navigation", "definition · declaration · implementation · typeDefinition"],
  ["References", "references · documentHighlight"],
  ["Intelligence", "hover · completion · signatureHelp · inlayHint"],
  ["Hierarchies", "call hierarchy · type hierarchy"],
  ["Refactoring", "rename · codeAction · executeCommand"],
  ["Formatting", "formatting · rangeFormatting"],
  ["Symbols", "documentSymbol · workspace/symbol"],
  ["Diagnostics", "publishDiagnostics (background cargo check) · pull diagnostics"],
  ["Workspaces", "didChangeWorkspaceFolders · watched files"],
];

const EDITORS = {
  "Zed": `// 1. Command palette → "zed: install dev extension" → rust-intelligence/editors/zed
// 2. settings.json
{
  "languages": {
    "Rust": { "language_servers": ["rust-intelligence", "!rust-analyzer"] }
  },
  "lsp": {
    "rust-intelligence": { "binary": { "path": "ridx", "arguments": ["lsp"] } }
  }
}`,
  "VS Code": `// settings.json: the rust-analyzer extension starts ridx instead
{
  "rust-analyzer.server.path": "ridx"
}`,
  "Neovim": `vim.lsp.config("ridx", {
  cmd = { "ridx" },
  filetypes = { "rust" },
  -- Cargo.lock first: a workspace member's own Cargo.toml is not the workspace root
  root_markers = { "Cargo.lock", "Cargo.toml" },
})
vim.lsp.enable("ridx")`,
  "Helix": `# languages.toml
[language-server.ridx]
command = "ridx"
args = ["lsp"]

[[language]]
name = "rust"
language-servers = ["ridx"]`,
};

const el = (tag, cls, html) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html !== undefined) e.innerHTML = html;
  return e;
};
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");

function tabs(boxId, keys, onSelect) {
  const box = document.getElementById(boxId);
  box.replaceChildren();
  const buttons = keys.map((k) => {
    const b = el("button", "chip");
    b.textContent = k;
    b.addEventListener("click", () => select(k));
    box.appendChild(b);
    return b;
  });
  function select(k) {
    buttons.forEach((b) => b.classList.toggle("on", b.textContent === k));
    onSelect(k);
  }
  select(keys[0]);
}

const mb = (v) => (v >= 1000 ? `${(v / 1024).toFixed(1)} GB` : `${v} MB`);
const sec = (v) => `${v < 10 ? v.toFixed(2) : v.toFixed(1)} s`;
// Rounded down, so a shown multiple never exceeds the measured one.
const times = (r) => `${r < 10 ? (Math.floor(r * 10) / 10).toFixed(1) : Math.floor(r)}×`;
const METRICS = [
  ["Peak memory", "peak_rss_mb", mb, "less memory"],
  ["CPU time for the session", "cpu_work_s", sec, "less CPU"],
  ["From start until ready to answer", "ready_s", sec, "faster start"],
];

// The smallest advantage over all repositories, so the headline holds for each of them.
function renderHero(repos) {
  const box = document.getElementById("hero-stats");
  // The repository where the advantage is smallest, named with its own figures.
  const least = (k) => repos.reduce((a, r) => (r.ra[k] / r.ridx[k] < a.ra[k] / a.ridx[k] ? r : a));
  const tones = ["rust", "amber", "cyan"];
  box.replaceChildren(...METRICS.map(([, k, f, word], i) => {
    const r = least(k);
    return el("div", "stat", `<span class="big ${tones[i]}">${times(r.ra[k] / r.ridx[k])}</span>${word} than rust-analyzer, at least<br>smallest gap, ${esc(r.name)}: ${f(r.ridx[k])} vs ${f(r.ra[k])}`);
  }),
    el("div", "stat", `<span class="big violet">${repos.length}</span>open-source repositories<br>${repos.map((r) => esc(r.name)).join(" · ")}`));
}

function renderRepo(r) {
  document.getElementById("res-meta").textContent = `${r.name} · ${r.ridx.files} files · ${r.ridx.requests} requests · errors: ridx ${r.ridx.errors}, rust-analyzer ${r.ra.errors}`;
  const rows = document.getElementById("res-rows");
  rows.replaceChildren(...METRICS.map(([label, k, f, word]) => el("div", "cap",
    `<div class="cap-head"><b>${label}</b><span class="mono rust">${times(r.ra[k] / r.ridx[k])} ${word}</span></div>
     <div class="bar-row"><span class="mono rust">ridx</span><div class="track"><div class="fr" style="width:0"></div></div><b class="mono">${f(r.ridx[k])}</b></div>
     <div class="bar-row"><span class="mono mute">rust-analyzer</span><div class="track"><div class="fa" style="width:0"></div></div><b class="mono mute">${f(r.ra[k])}</b></div>`)));
  requestAnimationFrame(() => METRICS.forEach(([, k], i) => {
    const top = Math.max(r.ridx[k], r.ra[k]);
    rows.children[i].querySelector(".fr").style.width = `${Math.max(1, (r.ridx[k] / top) * 100)}%`;
    rows.children[i].querySelector(".fa").style.width = `${Math.max(1, (r.ra[k] / top) * 100)}%`;
  }));
  const ms = ([p50, p95]) => `${p50} / ${p95}`;
  document.getElementById("res-lat").replaceChildren(
    el("div", "th", "method"), el("div", "th rust", "ridx"), el("div", "th", "rust-analyzer"),
    ...r.latency.flatMap(([m, a, b]) => [el("div", "mono", esc(m)), el("div", "mono", ms(a)), el("div", "mono mute", ms(b))]));
}

function renderResources(data) {
  if (!data || !data.repos || !data.repos.length) {
    document.getElementById("res-meta").textContent = "Measurements unavailable";
    return;
  }
  renderHero(data.repos);
  document.getElementById("res-src").textContent = `ridx ${data.commit} · ${data.date}`;
  const raw = document.getElementById("res-raw");
  raw.href = `https://github.com/alex09x/rust-intelligence/blob/main/${data.source}`;
  raw.textContent = data.source;
  const byName = Object.fromEntries(data.repos.map((r) => [r.name, r]));
  tabs("res-tabs", Object.keys(byName), (name) => renderRepo(byName[name]));
}

renderResources(RES);

const fmt = document.getElementById("fmt");
FORMAT.forEach(([n, s], i) => {
  const seg = el("div", "seg", `<span>${n}</span><span class="mute">${s}</span>`);
  seg.style.borderLeft = `3px solid ${TONES[i]}`;
  fmt.appendChild(seg);
});

const mtx = document.getElementById("mtx");
LSP.forEach(([c, m]) => { mtx.append(el("div", "", `<b>${c}</b>`), el("div", "m", m)); });

tabs("ed-tabs", Object.keys(EDITORS), (name) => {
  document.getElementById("ed-code").textContent = EDITORS[name];
});

document.querySelectorAll("[data-copy]").forEach((b) => b.addEventListener("click", async () => {
  try {
    await navigator.clipboard.writeText(document.getElementById(b.dataset.copy).textContent);
    b.textContent = "Copied";
  } catch {
    b.textContent = "Copy failed";
  }
  setTimeout(() => { b.textContent = "Copy"; }, 1400);
}));
